<template>
    <div class="ecom-element ecom-product-single ecom-product-single__variant-picker">
        <div class="ecom-product-single__variant-picker-wrapper" :class="{'ecom_not_hide_dropdown_arrow' : !data.settings?.hide_dropdown_arrow}">
            <div
                class="ecom-product-single__variant-picker-container"
                :data-picker-type="swatch_type"
                :class="liquid('wrapper_classes')"
                :data-ecom-placeholder="exporting ? '' : 'This product has only default variant'"
                :data-auto-variant-placeholder="autoVariantPlaceholderText"
            >
                <Liquid :data="liquids.assign_variant.code" />
                <div
                    class="ecom-product-single__variant-picker--main"
                    v-html="liquid('swatch_' + swatch_type + 's')"
                />
                <div
                    class="ecom-product-single__variant-picker--options"
                    v-html="liquid('options')"
                />
                <div class="ecom-product-single__variant-picker--json"
                    v-html="liquid('product_json')"
                />
            </div>
        </div>
    </div>
</template>

<script>
import { Liquid, Javascript, Element } from '@/mixins';
export default {
    name: 'productVariantPicker',
    presets:true,
    mixins: [Liquid, Javascript, Element],
    vendors: [],
    props: {
        data: {
            type: Object,
            default() {
                return {};
            }
        }
    },
    data(){
        return {
            jsreactives: ['type', 'show_option_selected', 'hide_unavaiable_variant', 'hide_soldout_variant', 'disable_style', 'prevents_product_image_changes', 'show_all_values_first_option', 'auto_variant_placeholder_text'],
            resize: {
                horizontal: true,
                vertical: false
            }
        }
    },
    computed: {
        element_id() {
            return this.data.id;
        },
        disable_style_name(){
            return this.data.settings?.hide_soldout_variant && this.data.settings?.disable_style ? `ecom-disable-style-${this.data.settings?.disable_style}`: "";
        },
        autoVariantPlaceholderText() {
            return this.lang(
                this.data.settings?.auto_variant_placeholder_text ?? '-',
                'auto_variant_placeholder_text',
                this.exporting === true ? { escape: true } : null
            );
        },
        javascript() {
            return function() {
                const $el = this.$el;
                if (!$el) return;

                const isLive = this.isLive;
                const $container = $el.querySelector('.ecom-product-single__variant-picker-container');
                if (!$container) return;

                const wrapper = $container.closest('.ecom-sections[data-section-id]');
                const updateSelected = this.settings.show_option_selected;
                const historyState = this.settings.history_state;
                const auto_variant_disable = this.settings.auto_variant_disable;
                const hide_soldout_variant = this.settings.hide_soldout_variant;
                const hide_unavaiable_variant = this.settings.hide_unavaiable_variant;
                const select_first_variant = this.settings.select_first_variant;
                const swatchType = this.settings.type;
                const prevents_product_image_changes = this.settings.prevents_product_image_changes;
                const autoselect_available_variant = hide_soldout_variant && hide_unavaiable_variant;
                const style_dropdown_labels = !this.settings.hasOwnProperty('show_option_selected') && !this.settings.show_option_selected;
                const show_all_first_option = this.settings.show_all_values_first_option;
                const selector = $el.querySelector('[name="id"]');
                const variantCount = selector ? parseInt(selector.getAttribute('ec-variants')) : 0;
                const autoVariantPlaceholder = $container.dataset.autoVariantPlaceholder ?? '-';

                const isHighVariantProduct = isLive && (variantCount > 250);
                const $section = $el.closest('.ecom-product-form--single');

                if(!$section) return;
                if(auto_variant_disable) {
                    if(swatchType !== 'dropdown') {
                        $section.classList.add('ecom_auto_variant_disable');
                    }
                    // xử lý trường hợp auto variant disable khi load trang
                    const swatchs = $container.querySelectorAll('.ecom-product-single__swatch-item');
                    // Dạng swatch
                    swatchs.forEach(function(swatch) {
                        swatch.classList.remove('ecom-box-active', 'ecom-button-active', 'ecom-image-active');
                    });
                    // Dạng dropdowm
                    $container.querySelectorAll('select.single-option-selector').forEach(function(select) {
                        const optionName = select
                            .closest('.selector-wrapper')
                            ?.querySelector('.ecom-product-variant--option-label-text')
                            ?.textContent
                            ?.trim() || '';
                        const placeholderText = autoVariantPlaceholder.replace(/\{option\}/g, function() {
                            return optionName;
                        });
                        const options = select.querySelectorAll('option');
                        options.forEach(function(option) {
                            option.removeAttribute('selected');
                        });
                        let option = select.querySelector('option[value=""]');
                        if (!option) {
                            option = document.createElement('option');
                            option.value = '';
                            select.prepend(option);
                        }
                        option.textContent = placeholderText;
                        option.setAttribute('selected', 'selected');

                        // Reset đúng cách cho Shopify
                        select.value = ''; // thay vì selectedIndex = 0

                        // Shopify yêu cầu bubbles=true
                        select.dispatchEvent(new Event('change', { bubbles: true }));
                    });
                }

                let pickerTimeout = null;
                if (!selector) return;

                const json = $el.querySelector('#' + selector.dataset.jsonProduct) || !isLive ? $el?.querySelector('[id^=product-json]') : null;
                if (!json) return;

                let product = null;
                try {
                    product = JSON.parse(json.innerHTML);
                } catch (e) {
                    return;
                }

                // ============================================
                // SHARED UPDATE FUNCTIONS
                // ============================================
                // Resolve a variant's image. featured_image can be null, or an object whose
                // `src` is missing depending on which Shopify JSON payload it came from
                // (some only expose `url`, some only carry featured_media). Returns null
                // when there is no usable image so callers never touch an undefined src.
                function getVariantImage(variant) {
                    if (!variant) return null;
                    const image = variant.featured_image || null;
                    const media = variant.featured_media || null;
                    const preview = media && media.preview_image ? media.preview_image : null;
                    const src = (image && (image.src || image.url))
                        || (preview && (preview.src || preview.url))
                        || null;
                    if (!src) return null;
                    return {
                        src: src,
                        alt: (image && image.alt) || (media && media.alt) || (preview && preview.alt) || ''
                    };
                }
                function ensureFirstOptionAllVisible() {
                    if (!show_all_first_option) return;
                    try {
                        // Enable and show all SELECT options for the first option (index 0)
                        $container.querySelectorAll('select[data-option-index="0"]').forEach((sel) => {
                            Array.from(sel.options).forEach((opt) => {
                                opt.disabled = false;
                                opt.classList && opt.classList.remove('ecom-variant-disable');
                                if (opt.style) opt.style.display = '';
                            });
                        });
                        // Enable and show all swatch items for the first option (index 0)
                        $section.querySelectorAll('.ecom-product-single__swatch-item[data-option-index="0"]').forEach((el) => {
                            el.classList.remove('ecom-variant-disable');
                            el.removeAttribute('disabled');
                            if (el.style) el.style.display = '';
                        });
                    } catch (e) {}
                }
                function updateBadge(variant) {

                    if($section.classList.contains('ecom_auto_variant_disable') && auto_variant_disable) return;
                    const $badgeBox = $section.querySelector('.ecom-product-single__price--badges');
                    if(!$badgeBox) return;
                    if(!variant) {
                        $badgeBox.querySelector('.ecom-product-single__price--badges-sold-out').style.display = 'none';
                        return;
                    }
                    if ($badgeBox) {
                        $badgeBox.querySelectorAll('span').forEach(function(element){
                            element.style.display = 'none';
                        });
                    }
                    if (variant) {
                        if (variant.available && variant.price < variant.compare_at_price) {
                            if ($badgeBox && $badgeBox.querySelector('.ecom-product-single__price--badges-sale')) {
                                const $saleBox = $badgeBox.querySelector('.ecom-product-single__price--badges-sale');
                                $saleBox.style.display = 'block';
                                let discount = 0;
                                discount = Math.round(((variant.compare_at_price - variant.price) * 100) / variant.compare_at_price);
                                if($saleBox.dataset.type === 'amount') {
                                    discount = window.EComposer.formatMoney(variant.compare_at_price - variant.price);
                                }
                                let text = $saleBox.dataset.text;
                                text = text.replace(/\{.*\}/g, discount);
                                $saleBox.innerHTML = text;
                            }
                        } else if (!variant.available) {
                            if ($badgeBox) {
                                $badgeBox.querySelector('.ecom-product-single__price--badges-sold-out').style.display = 'block';
                            }
                        }
                    }
                }

                function updateQuantity(variant) {
                    const $quantity = $section.querySelector('.ecom-product-single__quantity-input');
                    if ($quantity) {
                        const min_quantity = $quantity && $quantity.dataset.minValue?parseInt($quantity.dataset.minValue):'';
                        const max_quantity = $quantity && $quantity.dataset.maxValue?parseInt($quantity.dataset.maxValue):'';
                        if (!variant) {
                            $quantity.value = min_quantity && min_quantity>0 ? min_quantity: 1;
                            $quantity.setAttribute('disabled', 'disabled');
                            return;
                        } else if (!variant.available) {
                            if (min_quantity && min_quantity>0){
                                $quantity.value = min_quantity
                            }
                            $quantity.setAttribute('disabled', 'disabled');
                        } else {
                            if (!$quantity.value ||min_quantity && min_quantity>0 && ($quantity.value < min_quantity)){
                                $quantity.value = min_quantity;
                            }
                            $quantity.removeAttribute('disabled', 'disabled');
                        }
                        const inventory_quantity = variant.inventory_quantity;
                        const policy = variant.inventory_policy;
                        let max = max_quantity && max_quantity>0 ? max_quantity:9999;
                        if (variant.inventory_management && policy === 'deny') {
                            max = max_quantity && max_quantity>0 && max_quantity<inventory_quantity ? max_quantity:inventory_quantity;
                            if (inventory_quantity < min_quantity ) {
                                $quantity.value = min_quantity;
                            }else{
                                !$quantity.value|| min_quantity && min_quantity>0 && ($quantity.value < min_quantity)?$quantity.value = min_quantity:null;
                            }
                        }
                        if (inventory_quantity < 1 && policy == 'continue') {
                            !$quantity.value|| min_quantity && min_quantity>0 && ($quantity.value < min_quantity)?$quantity.value = min_quantity:null;
                            max = 999999;
                        }
                        if (variant && (inventory_quantity && inventory_quantity > min_quantity)|| variant && policy == 'continue'){
                            if(variant.inventory_management && policy === 'deny'){
                                max = max_quantity && max_quantity>0 && max_quantity<inventory_quantity ? max_quantity:inventory_quantity;
                            }else if(variant.inventory_management && policy === 'continue') {
                                max = 999999;
                            }
                            if ($quantity.value < min_quantity) {
                                $quantity.value = min_quantity;
                            }
                        }
                        if(max < 0) max = 0;
                        let quantity = parseInt($quantity.value);
                        if (!min_quantity && quantity > max) {
                            quantity = max;
                        }
                        quantity = isNaN(quantity) || !quantity ? 1 : quantity;
                        if(!min_quantity && !variant.available) {
                            quantity = 0;
                        }
                        quantity = quantity >= 0 ? quantity : 1;

                        $quantity.value = quantity;
                        $quantity.setAttribute('max', max);
                    }
                }

                // Slider trong Image.vue co listener 'move' tu ghi lai input[name="id"] theo
                // data-variant_id cua slide dich. Voi san pham nhieu variant, Liquid
                // `image.variants` khong liet ke du variant nen no ghi de nham sang variant
                // khac variant vua chon. Co nay bao cho Image.vue biet move la do code goi
                // sau khi doi variant, khong phai user thao tac slider.
                function markProgrammaticSliderMove($slider) {
                    if (!$slider) return;
                    $slider.dataset.ecomProgrammaticMove = '1';
                    // Fallback: neu event 'moved' khong ban (transition bi huy/khong doi slide)
                    // thi tu xoa co, tranh chan nham thao tac ke tiep cua user.
                    clearTimeout($slider._ecomProgrammaticMoveTimer);
                    $slider._ecomProgrammaticMoveTimer = setTimeout(function() {
                        delete $slider.dataset.ecomProgrammaticMove;
                    }, 1500);
                }

                function updateFeatured(variant) {
                    const $sliderBoxs = $section.querySelectorAll('.ecom-product-single__media--slider');

                    if ($sliderBoxs.length && variant) {
                        $sliderBoxs.forEach(function($sliderBox) {
                            const $slider = $sliderBox.querySelector('.ecom-product-single__media--featured');
                            if (!$slider) return;

                            // Early return if data-priority is 'featured'
                            if ($slider.getAttribute('data-priority') === 'featured') return;

                            // Early return if THIS slider is in gallery group mode (handled by Image.vue).
                            // Scoped to $sliderBox, not $section, so other Image elements on the same
                            // section that don't use gallery grouping still get updated here.
                            if ($sliderBox.querySelector('#ecom-single-product-default-variant')) return;

                            const slides = $slider.querySelectorAll('.ecom-product-single__media--image');
                            if (!slides?.length) return;

                            let matchedByVariantId = false;
                            slides.forEach(($slide, i) => {
                                const variantsId = $slide.dataset.variant_id?.split(',');
                                if (!variantsId?.length) return;

                                if (!variantsId.includes(String(variant.id))) return;

                                matchedByVariantId = true;
                                const index = parseInt($slide.dataset.index);
                                const current = $slider.ec_splide?.index ?? 0;

                                if (index !== current) {
                                    setTimeout(() => {
                                        if (!$slider.ec_splide) return;
                                        markProgrammaticSliderMove($slider);
                                        $slider.ec_splide.go(index);
                                    }, 100);
                                }
                            });

                            // Fallback for high-variant products (>250 variants): data-variant_id is not
                            // set on slides, so match by featured_image src instead.
                            const featuredImage = getVariantImage(variant);
                            if (!matchedByVariantId && featuredImage) {
                                const featuredSrc = featuredImage.src.split('?')[0];
                                const featuredFilename = featuredSrc.split('/').pop();
                                let fallbackIndex = -1;
                                if (!featuredFilename) return;
                                slides.forEach(($slide, i) => {
                                    const img = $slide.querySelector('img');
                                    const imgSrc = img?.src?.split('?')[0] || '';
                                    if (img && imgSrc.includes(featuredFilename)) {
                                        if (fallbackIndex === -1) fallbackIndex = $slide.dataset.index !== undefined ? parseInt($slide.dataset.index) : i;
                                    }
                                });
                                if (fallbackIndex >= 0 && fallbackIndex !== ($slider.ec_splide?.index ?? 0)) {
                                    setTimeout(() => {
                                        if (!$slider.ec_splide) return;
                                        markProgrammaticSliderMove($slider);
                                        $slider.ec_splide.go(fallbackIndex);
                                    }, 100);
                                }
                            }
                        });
                    } else if (getVariantImage(variant)) {
                        const featuredImage = getVariantImage(variant);
                        // Update ALL "single" layout Image elements on this section, not just the first.
                        const $imgBoxes = $section.querySelectorAll('.ecom-product-single__media--single .ecom-product-single__media--featured');
                        $imgBoxes.forEach(function($imgBox) {
                            if ($imgBox.getAttribute('data-priority') === 'featured') return;

                            const img = $imgBox.querySelector('img');
                            if (img) {
                                img.setAttribute('src', featuredImage.src);
                                img.setAttribute('alt', featuredImage.alt);
                                img.setAttribute('srcset', featuredImage.src);
                            }
                        });
                    }
                }

                function updateProductButtons(variant) {
                    const $submits = $section.querySelectorAll('.ecom-product-single__add-to-cart--submit');
                    if($submits.length) {
                        $submits.forEach(function($submit) {
                            if($section.classList.contains('ecom_auto_variant_disable') && auto_variant_disable) {
                                $submit.setAttribute('disabled', 'disabled');
                            } else {
                                if(variant) {
                                    if (variant.available || variant.inventory_management === null) {
                                        $submit.removeAttribute('disabled');
                                        if($submit.querySelector('.ecom-add-to-cart-text')) {
                                            if(!variant.inventory_management || (variant.inventory_management && variant.inventory_quantity > 0)) {
                                                $submit.querySelector('.ecom-add-to-cart-text').innerHTML = $submit.dataset.textAddCart;
                                                $submit.classList.remove('ecom-product-single__pre-order');
                                            }
                                            else if(variant.inventory_quantity <= 0 && variant.inventory_policy == 'continue') {
                                                $submit.querySelector('.ecom-add-to-cart-text').innerHTML = $submit.dataset.textPreOrder;
                                                $submit.classList.add('ecom-product-single__pre-order');
                                            }
                                        }
                                    } else {
                                        $submit.setAttribute('disabled', 'disabled');
                                        if($submit.querySelector('.ecom-add-to-cart-text')) {
                                            $submit.querySelector('.ecom-add-to-cart-text').innerHTML = $submit.dataset.textOutstock;
                                            $submit.classList.remove('ecom-product-single__pre-order');
                                        }
                                    }
                                } else {
                                    $submit.setAttribute('disabled', 'disabled');
                                    if($submit.querySelector('.ecom-add-to-cart-text')) {
                                        let checkNull = false;
                                        $container.querySelectorAll('.single-option-selector').forEach(function(selector) {
                                            if(selector.value === '') {
                                                checkNull = true;
                                                return;
                                            }
                                        })
                                        if(checkNull) {
                                            if(hide_unavaiable_variant){
                                                $submit.querySelector('.ecom-add-to-cart-text').innerHTML = $submit.dataset.textOutstock;
                                            }
                                            else if(hide_soldout_variant) {
                                                $submit.querySelector('.ecom-add-to-cart-text').innerHTML = $submit.dataset.textUnavailable;
                                            }
                                            else {
                                                $submit.querySelector('.ecom-add-to-cart-text').innerHTML = $submit.dataset.textAddCart;
                                            }
                                        } else {
                                            $submit.querySelector('.ecom-add-to-cart-text').innerHTML = $submit.dataset.textUnavailable;
                                        }
                                    }
                                }
                            }
                        })
                    }
                }

                function updateSwatch(variant) {
                    if($section.classList.contains('ecom_auto_variant_disable') && auto_variant_disable) {
                        return;
                    }
                    if (variant && variant.options.length) {
                        for (let i = 0; i < variant.options.length; i++) {
                            $section.querySelectorAll(`.ecom-product-single__swatch-item[data-option-index="${i}"][data-value="${variant.options[i].replace(/'/g, '\'').replace(/"/g, '\\"')}"]`)
                            .forEach((element) => {
                                element.parentNode.childNodes.forEach(function(el){
                                    if(el.classList) {
                                        el.classList.remove('ecom-box-active');
                                        el.classList.remove('ecom-button-active');
                                        el.classList.remove('ecom-image-active');
                                    }
                                });
                                element.classList.add('ecom-box-active');
                                element.classList.add('ecom-button-active');
                                element.classList.add('ecom-image-active');
                            });
                            $section.querySelectorAll(`select.ecom-product-single__swatch-select[data-option-index="${i}"]`).forEach(function(el){
                                el.value = variant.options[i];
                            })
                        }
                    }
                }

                function updateImageLabel(variant) {
                    const $labels = $section.querySelectorAll('.ecom-product-single__media-label');
                    if (variant) {
                        if($labels.length) {
                            $labels.forEach(function($label) {
                                $label.style.display = '';
                                const saleLabel = $label.querySelector('span.ecom-product-single__media-label-sale');
                                if(saleLabel) {
                                    saleLabel.style.display = (variant.available && variant.compare_at_price && variant.compare_at_price > variant.price) ? 'block' : 'none';
                                }
                                const soldoutLabel = $label.querySelector('.ecom-product-single__media-label-sold-out');
                                if(soldoutLabel) {
                                    soldoutLabel.style.display = variant.available ? 'none' : 'block';
                                }
                                const $badgeSale = $label.querySelector('.ecom-product-single__media-label--bage-sale');
                                if($badgeSale) {
                                    const saleBadgetType = $badgeSale.dataset.labelType;
                                    if (variant.compare_at_price > variant.price) {
                                        let text = $badgeSale.dataset.sale, sale = "";
                                        if (saleBadgetType === 'amount') {
                                            sale = variant.compare_at_price - variant.price;
                                            $badgeSale.style.display = 'inherit';
                                            $badgeSale.innerHTML = text.replace(/\[.*\]/g, window.EComposer.formatMoney(sale))
                                        } else {
                                            sale = Math.round(((variant.compare_at_price - variant.price) * 100) / variant.compare_at_price) ;
                                            $badgeSale.style.display = 'inherit';
                                            $badgeSale.innerHTML = (text.replace(/\[.*\]/g, Math.floor(sale)));
                                        }
                                        $badgeSale.style.display = !variant.available ? 'none' : 'inherit';
                                    } else {
                                        $badgeSale.style.display = 'none';
                                    }
                                }
                            })
                        }
                    }
                    else {
                        $labels.forEach(function($label) {
                            $label.style.display = 'none';
                        });
                    }
                }

                function updatePrice(variant) {
                    const $price_regular = $section.querySelectorAll('.ecom-product-single__price--regular');
                    const $prices = $section.querySelectorAll('.ecom-product-single__price--sale');
                    const $prices_percent_badge = $section.querySelectorAll('.ecom-product-single__price--badges-pecent-wrapper');
                    const $unit_price_wrapper = $section.querySelectorAll('.ecom-product_ground-price');
                    const $unit_price_container = $section.querySelector('.ecom-unit-price');
                    const $unit_price_measurement = $section.querySelectorAll('.ecom-ground-price_unit-price-measurement');

                    if (variant) {
                        $section.querySelector('shopify-payment-terms') && $section.querySelector('shopify-payment-terms').setAttribute('variant-id', variant.id);

                        if ($prices.length) {
                            innerPrice($prices, variant)
                        }

                        if($prices_percent_badge.length) {
                            $prices_percent_badge.forEach(function($percent) {
                                const saleBadgetType = $percent.dataset.labelType;
                                if(variant.compare_at_price && variant.compare_at_price > variant.price) {
                                    let salePercent = Math.round((variant.compare_at_price - variant.price) / variant.compare_at_price * 100);
                                    if(saleBadgetType === 'amount') {
                                        salePercent = window.EComposer.formatMoney(variant.compare_at_price - variant.price);
                                    }
                                    if($percent.querySelector('span')) {
                                        $percent.style.display = 'block';
                                        $percent.querySelector('span').innerText = `-${salePercent}%`
                                    }
                                } else {
                                    $percent.style.display = 'none';
                                }
                            })
                        }

                        if ($price_regular.length) {
                            $price_regular.forEach(function($price) {
                                $price.innerHTML = window.EComposer.formatMoney(variant.compare_at_price);
                                if (variant.compare_at_price > variant.price) {
                                    $price.style.display = 'inherit';
                                } else {
                                    $price.style.display = 'none';
                                }
                            })
                        }

                        if($unit_price_wrapper.length) {
                            $unit_price_wrapper.forEach(function($unit_price_wr) {
                                if(variant.unit_price) {
                                    $unit_price_wr.style.display = 'block';
                                    if($unit_price_container) $unit_price_container.style.display = 'block';
                                } else {
                                    $unit_price_wr.style.display = 'none';
                                    if($unit_price_container) $unit_price_container.style.display = 'none';
                                }
                                const $unit_price = $unit_price_wr.querySelector('.ecom-ground-price_unit-price');
                                if($unit_price) {
                                    $unit_price.innerHTML = window.EComposer.formatMoney(variant.unit_price);
                                }
                            })

                            if($unit_price_measurement.length) {
                                $unit_price_measurement.forEach(function($price) {
                                    if(variant.unit_price_measurement.reference_value != 1) {
                                        $price.innerHTML = variant.unit_price_measurement.reference_value + variant.unit_price_measurement.reference_unit;
                                    } else {
                                        $price.innerHTML = variant.unit_price_measurement.reference_unit;
                                    }
                                })
                            }
                        }

                        // Sync Afterpay/Square/payment placement widgets that rely on PerformanceObserver
                        // (which never fires on EComposer pages since we don't use Shopify section rendering).
                        if (wrapper) {
                            const priceInDollars = (variant.price / 100).toFixed(2);
                            wrapper.querySelectorAll('[data-amount]').forEach(function(el) {
                                el.setAttribute('data-amount', priceInDollars);
                            });
                        }
                    }

                    function innerPrice($prices, variant) {
                        $prices.forEach(function($price) {
                            if(!variant.compare_at_price || variant.compare_at_price < variant.price) {
                                $price.classList.add('ecom-product-single__price-normal');
                            }
                            else {
                                $price.classList.remove('ecom-product-single__price-normal');
                            }
                            $price.innerHTML = window.EComposer.formatMoney(variant.price);
                        })
                    }
                }

                function updateVariantAttribute(variant) {
                    const $barcode = $section.querySelector('.ecom-product-single__variant-attributes--barcode');
                    const $sku = $section.querySelector('.ecom-product-single__variant-attributes--sku');
                    if (variant) {
                        if ($barcode) {
                            $barcode.style.removeProperty('display');
                            $barcode.querySelector('.ecom-product-single__variant-attributes--text').innerHTML = `${variant.barcode ? variant.barcode : 'N/A'}`;
                        }
                        if ($sku) {
                            $sku.style.removeProperty('display');
                            $sku.querySelector('.ecom-product-single__variant-attributes--text').innerHTML = `${variant.sku ? variant.sku : 'N/A'}`;
                        }
                    } else {
                        if ($barcode) {
                            $barcode.style.display = 'none';
                        }
                        if ($sku) {
                            $sku.style.display = 'none';
                        }
                    }
                }

                function updateOptionSelected(variant) {
                    if(!variant || $section.classList.contains('ecom_auto_variant_disable') && auto_variant_disable) {
                        return;
                    }
                    const containers = $section.querySelectorAll('.ecom-product-single__variant-picker-container');
                    if (!containers.length || !variant) {
                        return false;
                    }
                    selector.dispatchEvent(new Event('change', { bubbles: true }));
                    containers.forEach($container => {
                        $container.querySelectorAll('.ecom-product-single__variant-picker--selected-value').forEach(function(el) {
                            el.remove();
                        });

                        if(auto_variant_disable && $section.classList.contains('ecom_auto_variant_disable')) {
                            $section.classList.remove('ecom_auto_variant_disable');
                            $section.querySelectorAll('.ecom-product-single__add-to-cart--submit').forEach(function(btn) {
                                btn.removeAttribute('disabled');
                            })
                        }

                        const dropdownTypeLabels = $el.querySelectorAll('.selector-wrapper label[for*="ecom-variant-selector"');
                        if (dropdownTypeLabels.length > 0) {
                            dropdownTypeLabels.forEach((label) => {
                                let baseLabel = label.dataset.optionLabelText;
                                const existing = label.querySelector('.ecom-product-variant--option-label-text');

                                if (baseLabel === undefined) {
                                    baseLabel = (existing ? existing.textContent : label.textContent)
                                        .replace(/:\s*$/, '')
                                        .trim();

                                    label.dataset.optionLabelText = baseLabel;
                                }

                                const afterContent = existing ? getComputedStyle(existing, '::after').content : '';
                                const hasColonAfter = afterContent === '":"';

                                label.querySelectorAll('.ecom-product-variant--option-label-text')
                                    .forEach((el) => el.remove());

                                const newLabelDom = document.createElement('span');
                                newLabelDom.className = 'ecom-product-variant--option-label-text';

                                const shouldAddColon =
                                    updateSelected && !hasColonAfter && !baseLabel.endsWith(':');

                                newLabelDom.innerText = `${baseLabel}${shouldAddColon ? ':' : ''}`;

                                label.prepend(newLabelDom);
                            });
                        }

                        if(!updateSelected) {
                            return 1;
                        }

                        const length = variant.options.length;
                        const $doms = $container.querySelectorAll('.selector-wrapper');
                        for (let i = 0; i < length; i++) {
                            if($doms[i]) {
                                $doms[i].querySelectorAll('label').forEach((el) => {
                                    const $selectedValue = document.createElement('span');
                                    $selectedValue.className = 'ecom-product-single__variant-picker--selected-value';
                                    $selectedValue.innerHTML =  variant.options[i];
                                    el.appendChild($selectedValue);
                                });
                            }
                            $container.querySelectorAll(`.ecom-product-single__picker--option-label[data-option-index="${i}"]`).forEach(function(el){
                                let tmp = document.createElement('span')
                                tmp.classList.add('ecom-product-single__variant-picker--selected-value');
                                tmp.innerHTML = variant.options[i];
                                el.appendChild(tmp);
                            })
                        }
                    })
                }

                function selectCallback(variant) {
                    updateBadge(variant);
                    if(!prevents_product_image_changes) {
                        updateFeatured(variant);
                    }
                    updateProductButtons(variant);
                    updateQuantity(variant);
                    updateSwatch(variant);
                    updatePrice(variant);
                    updateVariantAttribute(variant);
                    updateOptionSelected(variant);
                    updateImageLabel(variant);
                    window['Shopify'] = window['Shopify'] || {};
                    window['Shopify'].current_product = window['Shopify'].current_product || {};
                    window['Shopify'].current_product.current_variant = variant;
                    $section.dispatchEvent(new CustomEvent('ecomVariantChange', {detail: {variant: variant}}));
                }

                // ============================================
                // DECISION: High Variant vs Standard
                // ============================================
                if (isHighVariantProduct) {
                    initHighVariantProduct();
                } else {
                    initStandardVariantProduct();
                }

                function initHighVariantProduct() {
                    const sectionId = wrapper.dataset.sectionId;
                    if (!sectionId) {
                        console.error('Section ID not found for high variant product');
                        return;
                    }

                    // Set initial product URL for combined listings
                    if (!$section.dataset.productUrl) {
                        $section.dataset.productUrl = window.location.pathname;
                    }

                     let activeVariant = null;
                     // Ưu tiên lấy variant từ [data-selected-variant] (chứa variant JSON riêng biệt)
                    let variantScript = $section.querySelector('[data-selected-variant]');
                    // Fallback to product JSON script tag if [data-selected-variant] not found
                    if (!variantScript) {
                        variantScript = $section.querySelector('.ecom-product-single__variant-picker--json script');
                    }

                    if (variantScript && variantScript.innerHTML) {
                        try {
                            activeVariant = JSON.parse(variantScript.innerHTML);
                            // If parsed data is a product object (has variants array), extract selected variant
                            if (activeVariant && activeVariant.variants) {
                                activeVariant = activeVariant.selected_variant || activeVariant.selected_or_first_available_variant || null;
                            }
                            activeVariant = activeVariant && activeVariant.id ? activeVariant : null;

                            updateUIWithVariant(activeVariant);
                        } catch (e) {
                        }
                    }
                    // Attach event listeners
                    attachHighVariantListeners();
                    ensureFirstOptionAllVisible();

                    function attachHighVariantListeners() {
                        // Remove old listeners by cloning elements
                        $container.querySelectorAll('[data-option-value-id]').forEach(el => {
                            const newEl = el.cloneNode(true);
                            el.parentNode.replaceChild(newEl, el);
                        });

                        // Attach listeners to all elements with data-option-value-id
                        // For LI elements (radio, button, swatch)
                        $container.querySelectorAll('li[data-option-value-id]').forEach(element => {
                            element.addEventListener('click', onHighVariantChange);
                        });

                        // For SELECT dropdowns - attach to SELECT element, not OPTION
                        $container.querySelectorAll('select[data-option-index]').forEach(selectElement => {
                            selectElement.addEventListener('change', onHighVariantChangeFromSelect);
                        });

                        // For custom swatch selects
                        $container.querySelectorAll('.ecom-product-single__swatch-select').forEach(selectElement => {
                            selectElement.addEventListener('change', onHighVariantChangeFromSelect);
                        });
                    }

                    function onHighVariantChange(event) {
                        event.preventDefault();

                        const clickedElement = event.target.closest('[data-option-value-id]');
                        if (!clickedElement) return;

                        // Check if clicked element is already active (for non-select elements)
                        if (clickedElement.tagName === 'LI') {
                            // Nếu đã active rồi thì return, không fetch
                            if (clickedElement.classList.contains('ecom-box-active') ||
                                clickedElement.classList.contains('ecom-button-active') ||
                                clickedElement.classList.contains('ecom-image-active')) {
                                return;
                            }

                            // Mark as active for non-select elements
                            const optionIndex = clickedElement.dataset.optionIndex;
                            $container.querySelectorAll(`[data-option-index="${optionIndex}"]`).forEach(el => {
                                el.classList.remove('ecom-box-active', 'ecom-button-active', 'ecom-image-active');
                            });
                            clickedElement.classList.add('ecom-box-active', 'ecom-button-active', 'ecom-image-active');
                        }

                        // Perform fetch
                        performHighVariantFetch(clickedElement);
                    }

                    function onHighVariantChangeFromSelect(event) {
                        const selectElement = event.target;
                        const selectedOption = selectElement.options[selectElement.selectedIndex];

                        if (!selectedOption) return;

                        const newValue = selectedOption.value;
                        const optionIndex = parseInt(selectElement.dataset.optionIndex);

                        // Check for duplicate call
                        if (selectElement.dataset.lastSelectedValue === newValue) {
                            return;
                        }
                        selectElement.dataset.lastSelectedValue = newValue;

                        const selectedOptionValues = [];

                        // Collect from all selects
                        $container.querySelectorAll('select[data-option-index]').forEach(sel => {
                            const idx = parseInt(sel.dataset.optionIndex);

                            // Nếu đây là select vừa thay đổi, dùng giá trị mới
                            if (idx === optionIndex) {
                                if (selectedOption.dataset.optionValueId) {
                                    selectedOptionValues[idx] = selectedOption.dataset.optionValueId;
                                }
                            } else {
                                // Các select khác, đọc giá trị hiện tại
                                const opt = sel.options[sel.selectedIndex];
                                if (opt && opt.dataset.optionValueId) {
                                    selectedOptionValues[idx] = opt.dataset.optionValueId;
                                }
                            }
                        });

                        // Collect from active swatch items (override if exists)
                        $container.querySelectorAll('li[data-option-value-id].ecom-box-active, li[data-option-value-id].ecom-button-active, li[data-option-value-id].ecom-image-active').forEach(el => {
                            if (el.dataset.optionValueId && el.dataset.optionIndex) {
                                const idx = parseInt(el.dataset.optionIndex);
                                selectedOptionValues[idx] = el.dataset.optionValueId;
                            }
                        });

                        // Build params
                        const params = selectedOptionValues.filter(id => id).length > 0
                            ? `&option_values=${selectedOptionValues.filter(id => id).join(',')}`
                            : '';

                        // Check for combined listings
                        const oldProductUrl = $section.dataset.productUrl || window.location.pathname;
                        const newProductUrl = selectedOption.dataset.productUrl || oldProductUrl;
                        const isProductChange = newProductUrl && oldProductUrl !== newProductUrl;

                        // Build fetch URL
                        const fetchUrl = `${newProductUrl}?section_id=${sectionId}${params}`;

                        // Show loading state
                        $container.style.opacity = '0.5';
                        $container.style.pointerEvents = 'none';

                        fetch(fetchUrl)
                            .then(response => {
                                if (!response.ok) throw new Error('Network response was not ok');
                                return response.text();
                            })
                            .then(responseText => {
                                const html = new DOMParser().parseFromString(responseText, 'text/html');
                                let selectedVariant = null;

                                if (isProductChange) {
                                    // Combined listings: Replace entire product section
                                    const newSection = html.querySelector('.ecom-product-form--single');
                                    if (newSection) {
                                        $section.innerHTML = newSection.innerHTML;
                                        $section.dataset.productUrl = newProductUrl;

                                        // Re-initialize after replacement
                                        setTimeout(() => {
                                            initHighVariantProduct();
                                        }, 100);
                                    }
                                } else {
                                    // Update variant picker and related info
                                    const newContainer = html.querySelector('.ecom-product-single__variant-picker-container');
                                    if (newContainer) {
                                        $container.innerHTML = newContainer.innerHTML;
                                        attachHighVariantListeners();
                                        ensureFirstOptionAllVisible();

                                        // Focus back to the select element
                                        const focusTarget = $container.querySelector(`select[data-option-index="${optionIndex}"]`);
                                        if (focusTarget) {
                                            focusTarget.focus();
                                        }
                                    }

                                    // Extract and update variant info
                                    selectedVariant = updateVariantInfoFromHTML(html, optionIndex);
                                }

                                // Remove loading state
                                $container.style.opacity = '';
                                $container.style.pointerEvents = '';

                                // Update URL with history state if enabled
                                if (historyState && !isProductChange && selectedVariant && selectedVariant.id) {
                                    updateHighVariantHistoryUrl(selectedVariant);
                                }
                            })
                            .catch(error => {
                                console.error('Error fetching variant options:', error);
                                $container.style.opacity = '';
                                $container.style.pointerEvents = '';
                            });
                    }

                    function performHighVariantFetch(clickedElement) {
                        // Mirror standard variant behavior: remove data-priority so updateFeatured
                        // can navigate the slider after the user actively selects a variant.
                        const $sliders = $section.querySelectorAll('.ecom-product-single__media--featured');
                        $sliders.forEach(function(s) { s.removeAttribute('data-priority'); });

                        // Collect selected option value IDs
                        const selectedOptionValues = getSelectedOptionValueIds();

                        const params = selectedOptionValues.length > 0
                            ? `&option_values=${selectedOptionValues.join(',')}`
                            : '';

                        // Check for combined listings
                        const oldProductUrl = $section.dataset.productUrl || window.location.pathname;
                        const newProductUrl = clickedElement.dataset.productUrl || oldProductUrl;
                        const isProductChange = newProductUrl && oldProductUrl !== newProductUrl;

                        // Build fetch URL
                        const fetchUrl = `${newProductUrl}?section_id=${sectionId}${params}`;

                        // Show loading state
                        $container.style.opacity = '0.5';
                        $container.style.pointerEvents = 'none';

                        fetch(fetchUrl)
                            .then(response => {
                                if (!response.ok) throw new Error('Network response was not ok');
                                return response.text();
                            })
                            .then(responseText => {
                                const html = new DOMParser().parseFromString(responseText, 'text/html');
                                let selectedVariant = null;
                                if(auto_variant_disable && $section.classList.contains('ecom_auto_variant_disable')) {
                                    $section.classList.remove('ecom_auto_variant_disable');
                                    $section.querySelectorAll('.ecom-product-single__add-to-cart--submit').forEach(function(btn) {
                                        btn.removeAttribute('disabled');
                                    })
                                }
                                if (isProductChange) {
                                    // Combined listings: Replace entire product section
                                    const newSection = html.querySelector('.ecom-product-form--single');
                                    if (newSection) {
                                        $section.innerHTML = newSection.innerHTML;
                                        $section.dataset.productUrl = newProductUrl;

                                        // Re-initialize after replacement
                                        setTimeout(() => {
                                            initHighVariantProduct();
                                        }, 100);

                                    }
                                } else {
                                    // Update variant picker and related info
                                    const newContainer = html.querySelector('.ecom-product-single__variant-picker-container');
                                    if (newContainer) {
                                        $container.innerHTML = newContainer.innerHTML;
                                        attachHighVariantListeners();
                                        ensureFirstOptionAllVisible();

                                        // Focus back to similar element
                                        if (clickedElement.tagName === 'SELECT') {
                                            // For select, focus back to the select element
                                            const focusTarget = $container.querySelector(`select[data-option-index="${clickedElement.dataset.optionIndex}"]`);
                                            if (focusTarget && focusTarget.focus) {
                                                focusTarget.focus();
                                            }
                                        } else {
                                            // For other elements, use option-value-id
                                            const focusTarget = $container.querySelector(`[data-option-value-id="${clickedElement.dataset.optionValueId}"]`);
                                            if (focusTarget && focusTarget.focus) {
                                                focusTarget.focus();
                                            }
                                        }
                                    }

                                    // Extract and update variant info from the new HTML
                                    const clickIndex = clickedElement && clickedElement.dataset.optionIndex ? parseInt(clickedElement.dataset.optionIndex) : null;
                                    selectedVariant = updateVariantInfoFromHTML(html, clickIndex);
                                }

                                // Remove loading state
                                $container.style.opacity = '';
                                $container.style.pointerEvents = '';

                                // Update URL with history state if enabled
                                if (historyState && !isProductChange && selectedVariant && selectedVariant.id) {
                                    updateHighVariantHistoryUrl(selectedVariant);
                                }
                            })
                            .catch(error => {
                                console.error('Error fetching variant options:', error);
                                $container.style.opacity = '';
                                $container.style.pointerEvents = '';
                            });
                    }

                    function getSelectedOptionValueIds() {
                        const ids = [];
                        const addedIndexes = new Set(); // Track which option indexes we've added

                        // Get from radio/button/swatch items (LI elements)
                        $container.querySelectorAll('li[data-option-value-id].ecom-box-active, li[data-option-value-id].ecom-button-active, li[data-option-value-id].ecom-image-active').forEach(el => {
                            if (el.dataset.optionValueId && el.dataset.optionIndex) {
                                const optionIndex = parseInt(el.dataset.optionIndex);
                                if (!addedIndexes.has(optionIndex)) {
                                    ids[optionIndex] = el.dataset.optionValueId;
                                    addedIndexes.add(optionIndex);
                                }
                            }
                        });

                        // Get from select dropdowns (.single-option-selector) - Primary for dropdown type
                        $container.querySelectorAll('select.single-option-selector[data-option-index]').forEach(select => {
                            const optionIndex = parseInt(select.dataset.optionIndex);
                            // console.log("Processing select for option index:", optionIndex, select);
                            if (!addedIndexes.has(optionIndex)) {
                                const selectedOption = select.options[select.selectedIndex];
                                if (selectedOption && selectedOption.dataset.optionValueId) {
                                    ids[optionIndex] = selectedOption.dataset.optionValueId;
                                    addedIndexes.add(optionIndex);
                                }
                            }
                        });

                        // Get from custom swatch selects - Only if not already added
                        $container.querySelectorAll('select.ecom-product-single__swatch-select[data-option-index]').forEach(select => {
                            const optionIndex = parseInt(select.dataset.optionIndex);
                            if (!addedIndexes.has(optionIndex)) {
                                const selectedOption = select.options[select.selectedIndex];
                                if (selectedOption && selectedOption.dataset.optionValueId) {
                                    ids[optionIndex] = selectedOption.dataset.optionValueId;
                                    addedIndexes.add(optionIndex);
                                }
                            }
                        });

                        // Convert sparse array to dense array and filter out undefined
                        return ids.filter(id => id !== undefined);
                    }

                    function updateHighVariantHistoryUrl(variant) {
                        const newUrl = window.location.pathname + '?variant=' + variant.id;
                        window.history.replaceState({}, '', newUrl);
                    }

                    function updateVariantInfoFromHTML(html, clickIndex = null) {
                        let selectedVariant = null;

                        // Ưu tiên lấy từ [data-selected-variant] (chứa variant JSON riêng biệt, chính xác)
                        const selectedVariantScript = html.querySelector('[data-selected-variant]');

                        if (selectedVariantScript && selectedVariantScript.innerHTML) {
                            try {
                                selectedVariant = JSON.parse(selectedVariantScript.innerHTML);
                            } catch (e) {
                            }
                        }

                        // Fallback 1: product JSON script tag → extract selected variant
                        if (!selectedVariant) {
                            const variantScript = html.querySelector('.ecom-product-single__variant-picker--json script');

                            if (variantScript && variantScript.innerHTML) {
                                try {
                                    const parsed = JSON.parse(variantScript.innerHTML);
                                    if (parsed && parsed.variants) {
                                        selectedVariant = parsed.selected_variant || parsed.selected_or_first_available_variant || null;
                                    } else {
                                        selectedVariant = parsed;
                                    }
                                } catch (e) {
                                }
                            }
                        }

                        // Fallback 2: product JSON by ID
                        if (!selectedVariant) {
                            const productJson = html.querySelector('#' + selector.dataset.jsonProduct);
                            if (productJson) {
                                try {
                                    const productData = JSON.parse(productJson.innerHTML);
                                    selectedVariant = productData.selected_variant || productData.selected_or_first_available_variant || null;
                                } catch (e) {
                                }
                            }
                        }
                        if (selectedVariant) {
                            const variantInput = $section.querySelector('input[name="id"]');

                            if (variantInput) {
                                variantInput.value = selectedVariant.id;
                                variantInput.dispatchEvent(new Event('change', { bubbles: true }));
                            }

                            // Update UI
                            selectedVariant = selectedVariant.id ? selectedVariant : null;
                            // Auto-select available variant if current is not available
                            if (autoselect_available_variant && (!selectedVariant || !selectedVariant.available)) {
                                // Tìm và select các option values available cho options còn lại
                                const didChange = autoSelectAvailableOptions(clickIndex);
                                if (show_all_first_option && (clickIndex === 0 || clickIndex === null) && !didChange) {
                                    // Không có combo available khác, giữ UI hiện tại
                                    updateUIWithVariant(selectedVariant || null);
                                    return selectedVariant || null;
                                }
                                return null; // Exit vì sẽ trigger fetch mới hoặc đã fallback
                            }

                            updateUIWithVariant(selectedVariant);
                            return selectedVariant;
                        } else {

                            // Set empty value when no variant
                            const variantInput = $section.querySelector('input[name="id"]');
                            if (variantInput) {
                                variantInput.value = '';
                                variantInput.dispatchEvent(new Event('change', { bubbles: true }));
                            }

                            updateUIWithVariant(null);
                            return null;
                        }
                    }

                    function autoSelectAvailableOptions(clickIndex) {
                        // Tìm option values available (không disabled) và select chúng
                        const allOptions = $container.querySelectorAll('.single-option-selector[data-option-index], .ecom-product-single__swatch-item[data-option-index], .ecom-product-single__swatch-select[data-option-index]');
                        // Nhóm theo option index
                        const optionsByIndex = {};
                        allOptions.forEach(el => {
                            const index = el.dataset.optionIndex;
                            if (!optionsByIndex[index]) {
                                optionsByIndex[index] = [];
                            }
                            if(clickIndex !== null && parseInt(index) === clickIndex) {
                                // Chỉ auto select cho các option khác với option vừa click
                                return;
                            }
                            optionsByIndex[index].push(el);
                        });

                        let changed = false;
                        // Duyệt qua từng option index
                        Object.keys(optionsByIndex).sort().forEach(optionIndex => {
                            const elements = optionsByIndex[optionIndex];
                            // Nếu chưa có active, tìm element available đầu tiên
                            const availableElement = elements.find(el => {
                                if (el.tagName === 'LI') {
                                    const disabled = el.classList.contains('ecom-variant-disable') || el.style.display === 'none' || el.hasAttribute('disabled');
                                    const active = el.classList.contains('ecom-box-active') || el.classList.contains('ecom-button-active') || el.classList.contains('ecom-image-active');
                                    return !disabled && !active;
                                }
                                if (el.tagName === 'SELECT') {
                                    const opt = Array.from(el.options).find(o => !o.disabled && o.style.display !== 'none' && o.value !== '');
                                    if (opt) {
                                        el._ecomFirstAvailableOption = opt.value;
                                        return true;
                                    }
                                }
                                return false;
                            });
                            if (availableElement && !changed) {
                                if (availableElement.tagName === 'LI') {
                                    availableElement.click();
                                    changed = true;
                                } else if (availableElement.tagName === 'SELECT') {
                                    availableElement.value = availableElement._ecomFirstAvailableOption;
                                    availableElement.dispatchEvent(new Event('change', { bubbles: true }));
                                    changed = true;
                                }
                            }
                        });

                        return changed;
                    }

                    function updateUIWithVariant(variant) {
                        updateBadge(variant);
                        if (!prevents_product_image_changes) {
                            updateFeatured(variant);
                        }
                        updateOptionSelected(variant);
                        updateProductButtons(variant);
                        updateQuantity(variant);
                        updatePrice(variant);
                        updateVariantAttribute(variant);
                        updateImageLabel(variant);
                        updateSwatch(variant);
                        window['Shopify'] = window['Shopify'] || {};
                        window['Shopify'].current_product = window['Shopify'].current_product || {};
                        window['Shopify'].current_product.current_variant = variant;
                        $section.dispatchEvent(new CustomEvent('ecomVariantChange', {
                            detail: { variant: variant }
                        }));
                    }

                }

                // ============================================
                // STANDARD VARIANT PRODUCT (≤250 variants)
                // ============================================
                function initStandardVariantProduct() {
                    let isLoaded = false;
                    const singleOptionSelectors = $container.querySelectorAll('.single-option-selector');
                    if (!singleOptionSelectors.length) {
                        console.warn('No option selectors found');
                        return;
                    }

                    // Function để get selected variant từ các option selectors
                    function getSelectedVariantFromOptions() {
                        const selectedOptions = [];

                        singleOptionSelectors.forEach((select, index) => {
                            selectedOptions[index] = select.value;
                        });

                        // Tìm variant matching
                        return product.variants.find(variant => {
                            for (let i = 0; i < selectedOptions.length; i++) {
                                const optionKey = `option${i + 1}`;
                                if (variant[optionKey] !== selectedOptions[i]) {
                                    return false;
                                }
                            }
                            return true;
                        });
                    }

                    // Function để update hidden selector
                    function updateHiddenSelector(variant) {
                        if (variant) {
                            selector.value = variant.id;
                            selector.disabled = false;
                        } else {
                            selector.value = '';
                            selector.disabled = true;
                        }
                    }

                    // Function để update available options (hide soldout/unavailable)
                    function updateAvailableOptions() {
                        if (!hide_soldout_variant && !hide_unavaiable_variant) {
                            // Nhưng vẫn cần remove disabled class nếu có
                            $section.querySelectorAll('.ecom-variant-disable').forEach(el => {
                                el.classList.remove('ecom-variant-disable');
                                el.style.display = '';
                            });
                            // Keep first option fully visible when feature is on
                            if (show_all_first_option) {
                                ensureFirstOptionAllVisible();
                            }
                            return;
                        }

                        const selectedValues = [];
                        singleOptionSelectors.forEach(select => {
                            selectedValues.push(select.value);
                        });

                        singleOptionSelectors.forEach((select, selectIndex) => {
                            const optionIndex = parseInt(select.dataset.optionIndex);
                            const currentValue = select.value;

                            // SKIP option 0 when show_all_first_option is enabled - always keep it fully visible
                            if (show_all_first_option && optionIndex === 0) {
                                return; // Skip processing for first option
                            }

                            // Build available/soldout values for this selector
                            const availableValues = new Set();      // Values có variant available
                            const soldOutValues = new Set();        // Values có variant sold out
                            const allPossibleValues = new Set();    // Tất cả values có thể

                            // Check từng option value bằng cách build title pattern
                            product.variants.forEach(variant => {
                                // Build test pattern: lấy TẤT CẢ selected values (trừ current option)
                                // và check xem variant.title có match không
                                let matchesOtherSelections = true;

                                // Check tất cả các option ĐÃ CHỌN (không phải empty)
                                for (let i = 0; i < singleOptionSelectors.length; i++) {
                                    if (i === selectIndex) continue; // Skip current option đang check

                                    const selectedVal = selectedValues[i];
                                    if (!selectedVal || selectedVal === '') continue; // Skip empty

                                    const optionKey = `option${i + 1}`;
                                    if (variant[optionKey] !== selectedVal) {
                                        matchesOtherSelections = false;
                                        break;
                                    }
                                }

                                if (matchesOtherSelections) {
                                    const optionKey = `option${optionIndex + 1}`;
                                    const optionValue = variant[optionKey];

                                    allPossibleValues.add(optionValue);

                                    if (variant.available) {
                                        availableValues.add(optionValue);
                                    } else {
                                        soldOutValues.add(optionValue);
                                    }
                                }
                            });
                            // **UPDATE SELECT options**
                            Array.from(select.options).forEach(option => {
                                if (option.value === '') return; // Skip empty option

                                const optionValue = option.value;
                                let shouldDisable = false;
                                let shouldHide = false;

                                // Nếu value không tồn tại trong allPossibleValues → unavailable
                                if (!allPossibleValues.has(optionValue) && hide_unavaiable_variant) {
                                    shouldDisable = true;
                                    shouldHide = true;
                                }
                                // Nếu value chỉ có trong soldOutValues → sold out
                                else if (!availableValues.has(optionValue) && soldOutValues.has(optionValue) && hide_soldout_variant) {
                                    shouldDisable = true;
                                    shouldHide = hide_soldout_variant; // Chỉ hide khi setting được bật
                                }

                                if (shouldDisable) {
                                    option.disabled = true;
                                    option.classList.add('ecom-variant-disable');
                                } else {
                                    option.disabled = false;
                                    option.classList.remove('ecom-variant-disable');
                                }
                            });

                            // **UPDATE SWATCH ITEMS (LI)**
                            $section.querySelectorAll(`.ecom-product-single__swatch-item[data-option-index="${optionIndex}"]`).forEach(swatchItem => {
                                const value = swatchItem.dataset.value;
                                let shouldDisable = false;
                                let shouldHide = false;

                                // Nếu value không tồn tại trong allPossibleValues → unavailable
                                if (!allPossibleValues.has(value) && hide_unavaiable_variant) {
                                    shouldDisable = true;
                                    shouldHide = hide_unavaiable_variant; // Chỉ hide khi setting được bật
                                }
                                // Nếu value chỉ có trong soldOutValues → sold out
                                else if (!availableValues.has(value) && soldOutValues.has(value) && hide_soldout_variant) {
                                    shouldDisable = true;
                                    shouldHide = hide_soldout_variant; // Chỉ hide khi setting được bật
                                }

                                if (shouldDisable) {
                                    swatchItem.classList.add('ecom-variant-disable');
                                } else {
                                    swatchItem.classList.remove('ecom-variant-disable');
                                }

                            });

                            // **IMPORTANT: Nếu current value bị unavailable/soldout, reset về empty**
                            // Nhưng CHỈ reset nếu setting tương ứng được bật
                            const isUnavailable = !allPossibleValues.has(currentValue);
                            const isSoldOut = !availableValues.has(currentValue) && soldOutValues.has(currentValue);
                            const shouldResetValue =
                                    (isUnavailable && hide_unavaiable_variant) ||
                                    (isSoldOut && hide_soldout_variant);

                            if (currentValue && shouldResetValue) {
                            //    select.value = '';
                               // Update selectedValues để các option sau dùng giá trị đúng
                               selectedValues[selectIndex] = '';
                            }
                        });
                        // Always ensure first option remains fully visible
                        if (show_all_first_option) {
                            ensureFirstOptionAllVisible();
                        }
                    }

                    function updateVariantImages() {
                        if (swatchType !== 'image') return;

                        const selectedValues = [];
                        singleOptionSelectors.forEach(select => {
                            selectedValues.push(select.value);
                        });
                        singleOptionSelectors.forEach((select, selectIndex) => {
                            const optionIndex = parseInt(select.dataset.optionIndex);

                            // Update images for swatch items
                            $section.querySelectorAll(`.ecom-product-single__swatch-item[data-option-index="${optionIndex}"]`).forEach(swatchItem => {
                                const value = swatchItem.dataset.value;
                                const img = swatchItem.querySelector('img');
                                if (img) {
                                    const testOptions = [...selectedValues];
                                    testOptions[selectIndex] = value;

                                    // Tìm variant matching với TẤT CẢ các option đã được chọn
                                    let matchingVariant = product.variants.find(variant => {
                                        for (let i = 0; i < testOptions.length; i++) {
                                            // Bỏ qua option chưa chọn (empty value)
                                            if (!testOptions[i]) continue;

                                            const optionKey = `option${i + 1}`;
                                            if (variant[optionKey] !== testOptions[i]) {
                                                return false;
                                            }
                                        }
                                        return true;
                                    });

                                    // FALLBACK: Nếu không tìm thấy (L/Blue unavailable), tìm variant available có cùng option[0] (L/Red)
                                    if (!matchingVariant && show_all_first_option && testOptions[0]) {
                                        matchingVariant = product.variants.find(v => v.available && v.option1 === testOptions[0]);
                                    }

                                    const matchingImage = getVariantImage(matchingVariant);
                                    if (matchingImage) {
                                        img.setAttribute('src', matchingImage.src);
                                        img.setAttribute('alt', matchingImage.alt || value);
                                    }
                                }
                            });
                        });
                    }
                    // Main change handler
                    function onOptionChange() {
                        let variant = !isLoaded && select_first_variant ? product.variants[0] : getSelectedVariantFromOptions();
                        isLoaded = true;

                        // NEW LOGIC: When option 0 changes and result is unavailable, auto-adjust option 1, 2...
                        if (show_all_first_option && singleOptionSelectors[0] && singleOptionSelectors[0].dataset.justChanged === 'true') {
                            if (!variant || !variant.available) {
                                const selectedOptions = [];
                                singleOptionSelectors.forEach((select) => selectedOptions.push(select.value));
                                // Find available variant matching option[0]
                                const candidate = product.variants.find(v => (!hide_soldout_variant || v.available) && v.option1 === selectedOptions[0]);
                                if (candidate) {
                                    // Adjust option 1, 2... (but not 0)
                                    singleOptionSelectors.forEach((select, idx) => {
                                        if (idx === 0) return;
                                        const optionKey = `option${idx + 1}`;
                                        if (candidate[optionKey]) {
                                            select.value = candidate[optionKey];
                                        }
                                    });
                                    variant = candidate;
                                }
                            }
                        }

                        // Original auto-select logic for other cases
                        if (autoselect_available_variant && variant && !variant.available && singleOptionSelectors[0].dataset.justChanged !== 'true') {
                            const alternativeVariant = findAlternativeAvailableVariant(variant);
                            if (alternativeVariant) {
                                // Update selectors to match the alternative variant
                                singleOptionSelectors.forEach((select, index) => {
                                    const optionKey = `option${index + 1}`;
                                    select.value = alternativeVariant[optionKey];
                                });
                                variant = alternativeVariant;
                            }
                        }
                        // Update selector.value BEFORE dispatching change event
                        updateHiddenSelector(variant);

                        if (variant) {
                            selectCallback(variant);
                        } else {
                            // No variant selected or not available
                            selectCallback(null);
                        }
                        updateAvailableOptions();
                        updateVariantImages();


                        // Update URL if history state enabled
                        if (historyState && variant) {
                            const newUrl = window.location.pathname + '?variant=' + variant.id;
                            window.history.replaceState({}, '', newUrl);
                        }
                    }

                    function findAlternativeAvailableVariant(currentVariant) {
                        // Find which option was just changed
                        let changedOptionIndex = -1;
                        singleOptionSelectors.forEach((select, index) => {
                            if (select.dataset.justChanged === 'true') {
                                changedOptionIndex = index;
                            }
                        });

                        const selectedOptions = [];
                        singleOptionSelectors.forEach((select, index) => {
                            selectedOptions[index] = select.value;
                        });

                        let bestMatch = null;
                        let bestMatchScore = -1;

                        product.variants.forEach(variant => {
                            if (!variant.available) return;

                            // If we know which option was changed, it MUST match that option
                            if (changedOptionIndex >= 0) {
                                const optionKey = `option${changedOptionIndex + 1}`;
                                if (variant[optionKey] !== selectedOptions[changedOptionIndex]) {
                                    return; // Skip this variant - doesn't keep the changed option
                                }
                            }

                            // Calculate match score for other options
                            let score = 0;
                            for (let i = 0; i < selectedOptions.length; i++) {
                                const optionKey = `option${i + 1}`;
                                if (variant[optionKey] === selectedOptions[i]) {
                                    score++;
                                }
                            }

                            if (score > bestMatchScore) {
                                bestMatchScore = score;
                                bestMatch = variant;
                            }
                        });

                        return bestMatch;
                    }

                    // Attach change listeners with tracking for clicked option
                    singleOptionSelectors.forEach((select, selectIndex) => {
                        select.addEventListener('change', function() {
                            // Store which option was just changed
                            select.dataset.justChanged = 'true';
                            // Clear other selectors' justChanged flag
                            singleOptionSelectors.forEach((otherSelect, otherIndex) => {
                                if (otherIndex !== selectIndex) {
                                    delete otherSelect.dataset.justChanged;
                                }
                            });
                            onOptionChange();
                        });
                    });

                    // Initial load: select variant from URL or first available
                    function initializeSelection() {
                        // Try to get variant from URL
                        const urlParams = new URLSearchParams(window.location.search);
                        const variantIdFromUrl = urlParams.get('variant');

                        if (variantIdFromUrl) {
                            const variant = product.variants.find(v => v.id == variantIdFromUrl);
                            if (variant) {
                                // Set selectors to match this variant
                                singleOptionSelectors.forEach((select, index) => {
                                    const optionKey = `option${index + 1}`;
                                    select.value = variant[optionKey];
                                });
                                // A variant from the URL takes priority over "select first variant" -
                                // mark as loaded so onOptionChange() reads the selectors we just set
                                // instead of forcing product.variants[0].
                                isLoaded = true;
                            }
                        }

                        // Trigger initial update
                        onOptionChange();
                    }

                    // Initialize
                    initializeSelection();

                    // Keep this instance's hidden id field in sync when another
                    // Variant Picker instance sharing the same product form changes
                    // the variant (e.g. a swatch picker + a dropdown picker for the
                    // same option) - otherwise only the picker the shopper actually
                    // touched updates its own [name="id"], and the untouched
                    // duplicate's stale value can be the one submitted to the cart.
                    $section.addEventListener('ecomVariantChange', function(event) {
                        if (event.detail) {
                            updateHiddenSelector(event.detail.variant);
                        }
                    });

                    // Dropdown label styling
                    if (style_dropdown_labels) {
                        const dropdownTypeLabels = $el.querySelectorAll('.selector-wrapper label[for*="ecom-variant-selector"');
                        if (dropdownTypeLabels.length > 0) {
                            dropdownTypeLabels.forEach((label) => {
                                let baseLabel = label.dataset.optionLabelText;
                                if (baseLabel === undefined) {
                                    const existing = label.querySelector('.ecom-product-variant--option-label-text');
                                    baseLabel = (existing ? existing.textContent : label.textContent).replace(/:\s*$/, '').trim();
                                    label.dataset.optionLabelText = baseLabel;
                                }
                                label.querySelectorAll('.ecom-product-variant--option-label-text').forEach((el) => el.remove());
                                const newLabelDom = document.createElement('span');
                                newLabelDom.className = 'ecom-product-variant--option-label-text';
                                newLabelDom.innerText = `${baseLabel}:`;
                                label.prepend(newLabelDom);
                            });
                        }
                    }

                   $section.querySelectorAll('.ecom-product-single__swatch-item[data-option-index]').forEach((el) => {
                        el.addEventListener('click', function(event) {
                            event.preventDefault();

                            if (this.classList.contains('ecom-variant-disable')) {
                                return; // Don't allow clicking on disabled items
                            }

                            // Handle slider priority
                            const $sliders = $section.querySelectorAll('.ecom-product-single__media--featured');
                            let $slider = null;
                            if($sliders && $sliders.length) {
                                if($sliders.length > 1) {
                                    $sliders.forEach(function(slider) {
                                        if($slider) return;
                                        const width = isLive ? window.screen.width : window.innerWidth;
                                        if((width > 1024 && !slider.closest('.hide-on-desktop')) ||
                                        (width > 767 && width <= 1024 && !slider.closest('.hide-on-tablet')) ||
                                        (width <= 767 && !slider.closest('.hide-on-mobile'))) {
                                            $slider = slider;
                                        }
                                    });
                                } else {
                                    $slider = $sliders[0];
                                }
                                $slider && $slider.removeAttribute('data-priority');
                            }

                            // **UPDATED: Better active state handling**
                            if(this.classList.contains('ecom-button-active') ||
                            this.classList.contains('ecom-box-active') ||
                            this.classList.contains('ecom-image-active')) {
                                return; // Already active
                            }

                            // Remove active class from siblings
                            const optionIndex = this.dataset.optionIndex;
                            this.parentNode.querySelectorAll(`.ecom-product-single__swatch-item[data-option-index="${optionIndex}"]`).forEach(function(el){
                                el.classList.remove('ecom-button-active', 'ecom-box-active', 'ecom-image-active', 'ecom-image-button');
                            });

                            // Add active class based on type
                            this.classList.add('ecom-button-active', 'ecom-box-active', 'ecom-image-active');
                            if (swatchType === 'swatch_images') {
                                this.classList.add('ecom-image-button');
                            }

                            $section.classList.remove('ecom_auto_variant_disable');

                            // Update corresponding select
                            const correspondingSelect = $section.querySelector(`select.single-option-selector[data-option-index="${optionIndex}"]`);
                            if (correspondingSelect) {
                                correspondingSelect.value = this.dataset.value;
                                correspondingSelect.dispatchEvent(new Event('change'));
                            }
                        });
                    });

                    // **UPDATE 4: Enhanced custom select change handler**
                    const swatch_el = $section.querySelectorAll('.ecom-product-single__swatch-select');
                    if(swatch_el.length) {
                        swatch_el.forEach(function(element) {
                            element.addEventListener('change', function(e){
                                // Handle slider priority
                                const $sliders = $section.querySelectorAll('.ecom-product-single__media--featured');
                                let $slider = null;
                                if($sliders && $sliders.length) {
                                    if($sliders.length > 1) {
                                        $sliders.forEach(function(slider) {
                                            if($slider) return;
                                            const width = isLive ? window.screen.width : window.innerWidth;
                                            if((width > 1024 && !slider.closest('.hide-on-desktop')) ||
                                            (width > 767 && width <= 1024 && !slider.closest('.hide-on-tablet')) ||
                                            (width <= 767 && !slider.closest('.hide-on-mobile'))) {
                                                $slider = slider;
                                            }
                                        });
                                    } else {
                                        $slider = $sliders[0];
                                    }
                                    $slider && $slider.removeAttribute('data-priority');
                                }

                                let optionIndex = e.target.getAttribute('data-option-index');
                                let val = e.target.value;
                                $section.classList.remove('ecom_auto_variant_disable');

                                // **NEW: Update active state on swatch items to match select**
                                $section.querySelectorAll(`.ecom-product-single__swatch-item[data-option-index="${optionIndex}"]`).forEach(item => {
                                    if (item.dataset.value === val) {
                                        item.classList.add('ecom-button-active', 'ecom-box-active', 'ecom-image-active');
                                    } else {
                                        item.classList.remove('ecom-button-active', 'ecom-box-active', 'ecom-image-active');
                                    }
                                });

                                // Update corresponding hidden select
                                const correspondingSelect = $section.querySelector(`select.single-option-selector[data-option-index="${optionIndex}"]`);
                                if (correspondingSelect) {
                                    correspondingSelect.value = val;
                                    correspondingSelect.dispatchEvent(new Event('change'));
                                }
                            });
                        });
                    }
                }
            };
        },
        page_type () {
                return this.$store.getters['page/params'].page;
        },
        liquids() {
            const tagName = 'script';
            const liquids = {
                wrapper_classes: {
                    code: `{% if product.has_only_default_variant%}${this.exporting ? '' : ' ecom-placeholder-on-builder-mode ecom-force-show'} ecom-product-single__variant-picker--only-default{% endif%} ${this.disable_style_name}`,
