            if (this.swatch_type === 'shopify_color') {
                // swatch_images
                liquids.swatch_shopify_colors = {
                    code: `
                        {%- capture swatch_option_temp  -%}${this.lang(this.data.settings.option,'product_option_swatch')}{%- endcapture-%}
