                        ]
                    }
                });

                if (this.data.settings?.option_layout === 'radio') {
                    style.push({
                        group_alias: 'button:active',
                        options: {
                            group_title: this.$t('radio_button'),
                            group_name:'button_color_radio',
                            selector: ' .ecom-product-single__picker-radio-list-item'
                        },
                        modify: {
                            params: [
                                {
                                    position: 3,
                                    fields: [
                                        {
                                            name: 'min_width',
                                            label: this.$t('min_width'),
                                            type: 'number',
                                            options: {
                                                responsive: true,
                                                units: {
                                                    px: {
                                                        min: 0,
                                                        max: 200
                                                    },
                                                }
                                            },
                                            css:{
                                                properties:{
                                                    'min-width': ''
                                                }
                                            }
                                        },
                                    ]
                                }
                            ]
                        }
                    });
                }
            }
            if (this.data.settings?.type === 'radio') {
                style.push({
                    group_alias: 'button:active',
                    options: {
                        group_title: this.$t('radio_button'),
                        group_name:'button_radio',
                        selector: ' .ecom-product-single__picker-radio-list-item'
                    },
                    modify: {
                        params: [
                            {
                                position: 3,
                                fields: [
                                    {
                                        name: 'min_width',
                                        label: this.$t('min_width'),
                                        type: 'number',
                                        options: {
                                            responsive: true,
                                            units: {
                                                px: {
                                                    min: 0,
                                                    max: 200
                                                },
                                            }
                                        },
                                        css:{
                                            properties:{
                                                'min-width': ''
                                            }
                                        }
                                    },
                                ]
                            }
                        ]
                    }
                });
            }
            if (this.data.settings?.hide_soldout_variant && this.data.settings?.disable_style !== 'hide') {
                style.push({
                    group_title: this.$t('disabled_variants'),
                    group_name: 'disable_style',
                    selector: ' .ecom-product-single__variant-picker-wrapper .ecom-product-single__variant-picker-container',
                    params: [
                        {
                            name: 'border_color',
                            label: this.$t('border_color'),
                            type: 'color',
                            value: '#999999',
                            options: {
                                oneline: true,
                                global: {
                                    type: 'colors'
                                },
                                visible: (data) => data && this.data.settings?.disable_style
                            },
                            css:{
                                selector: ` .ecom-variant-disable:not(.ecom-image-active)>img, .ecom-variant-disable:not(.ecom-box-active), .ecom-variant-disable:not(.ecom-button-active), .ecom-variant-disable:not(.ecom-image-active)`,
                                properties:{
                                    'border-color': ''
                                }
                            },
                        },
                        {
                            name: 'cross_color',
                            label: this.$t('slash_cross_color'),
                            type: 'color',
                            value: '#999999',
                            options: {
                                oneline: true,
                                global: {
                                    type: 'colors'
                                },
                                visible: (data) => data && this.data.settings?.disable_style
                            },
                            css:{
                                selector: ' .ecom-variant-disable:before,  .ecom-variant-disable:after',
                                properties:{
                                    'background-color': ''
                                }
                            },
                        },
                        {
                            type: 'number',
                            name: 'width',
                            label: this.$t('slash_cross_width'),
                            value: '2px',
                            options: {
                                units: {
                                    px: {
                                        min: 1,
                                        max: 20,
                                        step: 1,
                                    }
                                },
                                visible: (data) => data && this.data.settings?.disable_style
                            },
                            css: {
                            properties: {
                                'width': '%value%'
                            },
                            selector: ' .ecom-variant-disable:before,  .ecom-variant-disable:after',
                            }
                        },
                        {
                            type: 'number',
                            name: 'height',
                            label: this.$t('slash_cross_height'),
                            value: '85%',
                            options: {
                                units: {
                                    '%': {
                                        min: 0,
                                        max: 100,
                                        step: 1,
                                    }
                                },
                                visible: (data) => data && this.data.settings?.disable_style
                            },
                            css: {
                            properties: {
                                'height': '%value%'
                            },
                            selector: ' .ecom-variant-disable:before,  .ecom-variant-disable:after',
                            }
                        },
                        {
                            type: 'number',
                            name: 'disable_opacity',
                            label: this.$t('opacity'),
                            value: 0.4,
                            options: {
                                step: 0.01,
                                min: 0,
                                max: 1,
                                responsive: true,
                            },
                            css: {
                                properties: {
                                    'opacity': '%value%'
                                },
                                selector: ' .ecom-variant-disable',
                            }
                        }
                    ]
                });
            }
            if (
                this.data.settings?.type === 'dropdown' ||
                this.data.settings?.option_layout === 'dropdown'
            ) {
                style.push({
                    group_alias: 'input',
                    options: {
                        group_title: this.$t('dropdown'),
                        group_name:'dropdown',
                        selector: ' .ecom-product-single__swatch-select, .single-option-selector'
                    },
                    modify: {
                        remove: {
                            index: 4, length: 1
                        }
                    }
                });
            }

            return style;
        }
    },
};
</script>
